-- Payments in instalments (25 November 2026): a purchase, a loan or another split payment followed on its own,
-- with its calendar. It travels with the finances like the other entities (contract below). Each instalment paid is
-- an ordinary movement linked by its external_id; nothing here moves money.
CREATE TABLE IF NOT EXISTS public.finance_installment_plans (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id) ON DELETE CASCADE,
    workspace_id uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
    deleted_at timestamptz,
    name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 200),
    kind text NOT NULL CHECK (kind IN ('purchase','loan','other')),
    total_minor bigint NOT NULL CHECK (total_minor > 0),
    installment_count integer NOT NULL CHECK (installment_count BETWEEN 1 AND 600),
    first_due_date timestamptz NOT NULL,
    agreed_installment_minor bigint CHECK (agreed_installment_minor IS NULL OR agreed_installment_minor > 0),
    costs_minor bigint NOT NULL DEFAULT 0 CHECK (costs_minor >= 0),
    already_recorded boolean NOT NULL DEFAULT false,
    paid_before_count integer NOT NULL DEFAULT 0 CHECK (paid_before_count >= 0),
    paid_before_minor bigint NOT NULL DEFAULT 0 CHECK (paid_before_minor >= 0),
    schedule jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(schedule) = 'array' AND jsonb_array_length(schedule) <= 600),
    notes text NOT NULL DEFAULT '',
    is_archived boolean NOT NULL DEFAULT false,
    account_id uuid,
    PRIMARY KEY(owner_id, workspace_id, id),
    FOREIGN KEY(owner_id, workspace_id) REFERENCES public.finance_workspaces(owner_id, id),
    FOREIGN KEY(owner_id, workspace_id, account_id) REFERENCES public.finance_accounts(owner_id, workspace_id, id)
);
ALTER TABLE public.finance_installment_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.finance_installment_plans FORCE ROW LEVEL SECURITY;
REVOKE ALL ON public.finance_installment_plans FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.finance_installment_plans TO authenticated;
GRANT ALL ON public.finance_installment_plans TO service_role;
CREATE POLICY owner_select ON public.finance_installment_plans FOR SELECT TO authenticated USING ((SELECT auth.uid()) = owner_id);
CREATE POLICY owner_insert ON public.finance_installment_plans FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = owner_id);
CREATE POLICY owner_update ON public.finance_installment_plans FOR UPDATE TO authenticated
    USING ((SELECT auth.uid()) = owner_id) WITH CHECK ((SELECT auth.uid()) = owner_id);
CREATE TRIGGER stamp_record BEFORE INSERT OR UPDATE ON public.finance_installment_plans
    FOR EACH ROW EXECUTE FUNCTION finance_private.stamp_record();
CREATE TRIGGER a_workspace_lock BEFORE INSERT OR UPDATE ON public.finance_installment_plans FOR EACH ROW EXECUTE FUNCTION finance_private.lock_workspace();
CREATE TRIGGER z_workspace_revision AFTER INSERT OR UPDATE ON public.finance_installment_plans FOR EACH ROW EXECUTE FUNCTION finance_private.touch_workspace();
